            }
        }

        wait(1);
    }
}

fn how_many_players() -> i32 {
    last_key(); // Discard any pre-existing input

    draw_string(80, 40, "How many players (1 or 2)?", Color::White, true);

    loop {
        if let Some(c) = last_key() {
            if c == '1' {
                return 1;
            }
            if c == '2' {
