        Direction::Left => Point { x: p.x - 1, y: p.y },
        Direction::Right => Point { x: p.x + 1, y: p.y },
        Direction::Up => Point { x: p.x, y: p.y - 1 },
        Direction::Down => Point { x: p.x, y: p.y + 1 },
    }
}

fn read_input_and_delay() -> bool {
    wait(80);
    unsafe {
        let mut desired = [
            SNAKES[0].direction,
            SNAKES[1].direction
