        SNAKES[1].color = LIGHT_MAGENTA;
    }

    loop {
        clear(BACKGROUND);
        let players = how_many_players();

        unsafe {
            // Reset scores and lives at the start of each new game
            SNAKES[0].lives = 5;
            SNAKES[1].lives = 5;
            SNAKES[0].score = 0;
            SNAKES[1].score = 0;

            // Kill off player 2 right away if we're in 1-player mode
            if players == 1 {
                SNAKES[1].lives = 0;
            }

            let mut level = 1;
            let mut pickup_count = 0;
