    ];

    let mut text_width = 0;
    for &ch in s.as_bytes() {
        if ch >= 32 && ch < 128 {
            text_width += ((FONT[(ch - 32) as usize] >> 28) + 1) as usize;
        }
    }

    let mut x = (WIDTH - text_width) / 2;

    for &ch in s.as_bytes() {
        if ch < 32 || ch >= 128 {
            continue;
        }
        let mut glyph = FONT[(ch - 32) as usize];
        let width = (glyph >> 28) as usize;
        for u in x..x + width {
            for v in y..y + 5 {
                if (glyph & 1) == 1 {
                    density[id(u, v)] = 3.0;
                }
                glyph >>= 1;
            }
        }
        if width > 0 {
            x += width + 1;
        }
    }
