        if let Some(idx) = idx {
            if idx < FONT.len() {
                let mut glyph = FONT[idx];
                let width = (glyph >> 28) as usize;
                for u in x..x + width {
                    for v in y..y + 5 {
                        if glyph & 1 == 1 {
                            density[id(u, v)] = 3.0;
                        }
                        glyph >>= 1;
                    }
                }
                x += width + 1;
            }
        }
    }
}

