}

impl From<char> for Token {
    fn from(c: char) -> Self {
        if c == '~' {
            return Token::Tilde;
        }
        if c == ':' {
            return Token::Colon;
        }
        if c == '.' {
            return Token::Period;
        }
        if c.is_digit(10) {
            return Token::Number;
        }
        if c.is_ascii_alphabetic() {
            return Token::Letter;
        }
        for &ch in TILE_LOOKUP.iter() {
            if c == ch {
                return Token::Tile;
            }
        }
        Token::Unknown
    }
}

